import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential

def extract_tables(payload, config=None):
    config = config or {}
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY environment variables must be set.")

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    poller = document_intelligence_client.begin_analyze_document(
        "prebuilt-layout",
        analyze_request=payload,
        content_type="application/octet-stream"
    )
    analyze_result = poller.result()

    extracted_tables = []
    if analyze_result.tables:
        for table in analyze_result.tables:
            rows_map = {}
            for cell in table.cells:
                if cell.row_index not in rows_map:
                    rows_map[cell.row_index] = {}
                rows_map[cell.row_index][cell.column_index] = cell.content

            current_table_rows = []
            for row_idx in sorted(rows_map.keys()):
                row_cells = []
                for col_idx in sorted(rows_map[row_idx].keys()):
                    row_cells.append(rows_map[row_idx][col_idx])
                current_table_rows.append(row_cells)
            extracted_tables.append(current_table_rows)

    result = extracted_tables
    return result
